public static void check(Solution solution) {
    assert Arrays.equals(solution.replaceWords(new int[]{"a","aa","aaa"}, "aaaa aaa aa a"), a a a a);
    assert Arrays.equals(solution.replaceWords(new int[]{"base","bat","ba"}, "baseball batman bat"), ba ba ba);
    assert Arrays.equals(solution.replaceWords(new int[]{"dog","cat"}, "dog cat"), dog cat);
